// Input horror content manually or from webhook
const manualContent = {
  title: "{{ $json.title || 'Breaking: New Horror Movie Announced' }}",
  link: "{{ $json.link || 'https://example.com/horror-news' }}",
  description: "{{ $json.description || 'An exciting new horror project is in development, promising to deliver terrifying experiences for horror fans everywhere.' }}",
  categories: {{ $json.categories || ['horror', 'movies'] }},
  imageUrl: "{{ $json.imageUrl || '' }}",
  manualEntry: true,
  timestamp: new Date().toISOString()
};

return [{ json: manualContent }];

// Process and enhance manual horror content
const crypto = require('crypto');
const item = $input.first().json;

const contentHash = crypto
  .createHash('md5')
  .update(item.title + item.link + item.timestamp)
  .digest('hex');

const horrorContent = {
  idempotencyKey: `manual-${contentHash}`,
  title: item.title,
  link: item.link,
  description: item.description,
  pubDate: item.timestamp || new Date().toISOString(),
  categories: item.categories || ['horror'],
  imageUrl: item.imageUrl || '',
  horrorTags: generateHorrorTags(item.title),
  engagementScore: 90, // Manual content gets high score
  contentHash: contentHash,
  manualEntry: true
};

return [{ json: horrorContent }];

function generateHorrorTags(title) {
  const horrorKeywords = [
    'horror', 'scary', 'terror', 'nightmare', 'creepy',
    'paranormal', 'supernatural', 'slasher', 'thriller',
    'ghost', 'vampire', 'zombie', 'monster', 'dark',
    'haunting', 'possession', 'occult', 'gore', 'suspense'
  ];

  const tags = ['horror', 'featured'];
  const titleLower = title.toLowerCase();

  for (const keyword of horrorKeywords) {
    if (titleLower.includes(keyword) && !tags.includes(keyword)) {
      tags.push(keyword);
    }
  }

  return tags.slice(0, 8);
}

// Parse AI response and prepare YouTube data
const aiResponse = $input.first().json;
const originalContent = $input.first().json;
let parsedContent;

try {
  parsedContent = typeof aiResponse.message === 'string' 
    ? JSON.parse(aiResponse.message) 
    : aiResponse.message;
} catch (error) {
  parsedContent = {
    title: originalContent.title || 'Horror Content - Manual',
    description: originalContent.description || 'Manually curated horror content',
    tags: originalContent.horrorTags || ['horror'],
    categoryId: 1
  };
}

const horrorData = {
  idempotencyKey: originalContent.idempotencyKey,
  snippet: {
    title: parsedContent.title || originalContent.title,
    description: parsedContent.description || originalContent.description,
    categoryId: parsedContent.categoryId || 1,
    tags: parsedContent.tags || originalContent.horrorTags,
    defaultLanguage: 'en',
    defaultAudioLanguage: 'en'
  },
  status: {
    privacyStatus: 'public',
    selfDeclaredMadeForKids: false
  },
  contentDetails: {
    caption: 'true'
  },
  metadata: {
    uploadDate: new Date().toISOString(),
    horrorGenre: true,
    contentRating: 'mature',
    originalLink: originalContent.link,
    engagementScore: originalContent.engagementScore,
    manualEntry: true,
    featured: true
  }
};

return { json: horrorData };

// Format premium tweet for manual content
const horrorContent = $input.first().json;

const tweet = {
  idempotencyKey: horrorContent.idempotencyKey + '-twitter',
  text: `🎃 **FEATURED HORROR CONTENT** 🎃\n\n${horrorContent.title}\n\n${horrorContent.description.substring(0, 80)}...\n\n🔗 ${horrorContent.link}\n\n#Horror #HorrorCommunity #Scary #Terror #HorrorMovies #Featured`,
n  media: horrorContent.imageUrl || null
};

return { json: tweet };

